const entry = $input.first().json;
const payload = entry.body && typeof entry.body === 'object' && !Array.isArray(entry.body) ? entry.body : entry;
const id = typeof payload.request_id === 'string' ? payload.request_id.trim() : '';
const email = typeof payload.email === 'string' ? payload.email.trim() : '';
const intent = typeof payload.intent === 'string' ? payload.intent.trim() : '';
const errors = [];
if (!/^[A-Za-z0-9_-]{3,64}$/.test(id)) errors.push('request_id must be 3-64 letters, digits, underscores or hyphens');
if (!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(email) || email.length > 254) errors.push('email must be a valid address');
if (!['support', 'sales', 'other'].includes(intent)) errors.push('intent must be support, sales, or other');
return [{json:{request_id:id || null, valid:errors.length===0, errors, intent:errors.length===0?intent:null}}];

const v = $input.first().json;
const status = v.valid ? 200 : 400;
return [{json:{statusCode:status, body: v.valid ? {ok:true, request_id:v.request_id, provider:'local-mock', result:{route:v.intent==='support'?'helpdesk':v.intent==='sales'?'sales-queue':'general', accepted:true}} : {ok:false, request_id:v.request_id, errors:v.errors}}}];
